// Normalize the four sources into one brief payload.
// Items arrive appended from Merge; recover each source by node name.
function grab(nodeName) {
  try { return $(nodeName).all().map(i => i.json); } catch (e) { return null; }
}
const accounts = grab('MoneyMatter Accounts');
const subs = grab('MoneyMatter Subscriptions');
const calendar = grab('Google Calendar Today');
const tasks = grab('TickTick Open Tasks');
return [{
  json: {
    date: new Date().toISOString().slice(0, 10),
    sections: {
      accounts: accounts || 'UNAVAILABLE',
      upcomingSubscriptions: subs || 'UNAVAILABLE',
      calendarToday: calendar || 'UNAVAILABLE',
      openTasks: tasks || 'UNAVAILABLE'
    }
  }
}];

// ==== LLM SUMMARY (STUB) — replace with a real LLM call ====
// Feed PROMPT + JSON.stringify($json.sections) to your LLM and use its
// text output as `briefText`. Keep it under ~3500 chars for Telegram.
const PROMPT = `You are Hermes, writing Lloyd's 07:00 Manila morning brief.\nInput JSON has: accounts (balances), upcomingSubscriptions (next charges), calendarToday (events), openTasks (todos). Sections marked UNAVAILABLE were unreachable — say so in one short line.\nWrite a compact Telegram-friendly brief:\n☀️ Good morning header with date\n💰 Money: total cash position + any subscription charging in the next 3 days\n📅 Today: events with times (Asia/Manila)\n✅ Tasks: top 3-5 open tasks\nEnd with one short focus suggestion. Plain text, minimal markdown, no preamble.`;

const s = $json.sections;
const lines = [
  `☀️ Morning brief — ${$json.date}`,
  '',
  `💰 Accounts: ${s.accounts === 'UNAVAILABLE' ? 'source unavailable' : (Array.isArray(s.accounts) ? s.accounts.length + ' account(s) fetched' : 'ok')}`,
  `🔁 Subscriptions: ${s.upcomingSubscriptions === 'UNAVAILABLE' ? 'source unavailable' : 'fetched'}`,
  `📅 Calendar: ${s.calendarToday === 'UNAVAILABLE' ? 'source unavailable' : 'fetched'}`,
  `✅ Tasks: ${s.openTasks === 'UNAVAILABLE' ? 'source unavailable' : 'fetched'}`,
  '',
  '(LLM summary stub — wire a real model call here using the PROMPT in this node.)'
];
return [{ json: { prompt: PROMPT, briefText: lines.join('\n') } }];
